-- BREAKS in the mysql CLI: it sends everything up to the
-- FIRST semicolon, before the procedure body is finished
CREATE PROCEDURE BadExample()
BEGIN
  DECLARE x INT;
  SET x = 1;
  SELECT x;
END;

DELIMITER $$

CREATE PROCEDURE GetActiveCustomers()
BEGIN
  DECLARE minOrders INT;
  SET minOrders = 1;
  SELECT CustomerId, CustomerName
  FROM Customers
  WHERE OrderCount >= minOrders;
END$$

DELIMITER ;
